/**
 * Binary storage for the school's files (logo). Keys are relative names
 * generated by the application; adapters scope them to the current tenant.
 */
export interface AssetStoragePort {
  save(key: string, content: Uint8Array): Promise<void>;
  /** `null` when the file does not exist. */
  read(key: string): Promise<Uint8Array | null>;
  /** Idempotent. */
  delete(key: string): Promise<void>;
}

export const ASSET_STORAGE = Symbol('AssetStoragePort');
